const canvas = document.getElementById('matrix');
const ctx = canvas.getContext('2d');
const FONT_SIZE = 14;
const STEP = 2; 
function resizeCanvas() {
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;
}
resizeCanvas();
window.addEventListener('resize', () => { resizeCanvas(); cols = Math.floor(canvas.width / (FONT_SIZE * STEP)); drops = Array(cols).fill(1); });
const chars = '01アカサタナハマ<>{}[]#$%&*';
let cols = Math.floor(canvas.width / (FONT_SIZE * STEP));
let drops = Array(cols).fill(1);
let lastMatrix = 0;
function drawMatrix(ts) {
  if (ts - lastMatrix > 60) { // ~16fps
    lastMatrix = ts;
    ctx.fillStyle = 'rgba(2,12,2,0.07)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.font = FONT_SIZE + 'px Share Tech Mono';
    for (let i = 0; i < drops.length; i++) {
      const ch = chars[Math.floor(Math.random() * chars.length)];
      ctx.fillStyle = drops[i] * FONT_SIZE < 50 ? '#00ff41' : '#00882244';
      ctx.fillText(ch, i * FONT_SIZE * STEP, drops[i] * FONT_SIZE);
      if (drops[i] * FONT_SIZE > canvas.height && Math.random() > 0.975) drops[i] = 0;
      drops[i]++;
    }
  }
  requestAnimationFrame(drawMatrix);
}
requestAnimationFrame(drawMatrix);

// Efecto de escribir
window._typingLines = [
  'cat SobreMi.txt',
  'ping AleixCrespo.es',
  'ssh aleix@portfolio.dev',
  'nmap -sV localhost',
  'git commit -m "A seguir aprendiendo"',
];
let li = 0, ci = 0, deleting = false;
const typedEl = document.getElementById('typed');
function type() {
  const lines = window._typingLines;
  const cur = lines[li % lines.length];
  if (!deleting) {
    typedEl.textContent = cur.slice(0, ++ci);
    if (ci === cur.length) { deleting = true; setTimeout(type, 1800); return; }
  } else {
    typedEl.textContent = cur.slice(0, --ci);
    if (ci === 0) { deleting = false; li = (li+1) % lines.length; }
  }
  setTimeout(type, deleting ? 35 : 75);
}
setTimeout(type, 3400);

